841: pub fn doc_text(doc: &Value) -> String {
842:     fn walk(v: &Value, out: &mut String) {
843:         if let Some(t) = v["text"].as_str() {
844:             out.push_str(t)
845:         }
846:         if let Some(items) = v["content"].as_array() {
847:             for c in items {
848:                 walk(c, out)
849:             }
850:         }
851:         if ["paragraph", "heading", "listItem", "taskItem", "tableRow"]
852:             .contains(&v["type"].as_str().unwrap_or(""))
853:         {
854:             out.push('\n')
